package com.spendwise.controller;
import com.spendwise.model.*;import com.spendwise.repo.*;import com.spendwise.service.CurrentUser;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.util.*;import java.util.stream.*;
@RestController @RequestMapping("/api") public class DashboardController{
 private final TransactionRepository tx;private final BudgetRepository budgets;private final SavingsGoalRepository goals;private final CurrentUser current;
 public DashboardController(TransactionRepository t,BudgetRepository b,SavingsGoalRepository g,CurrentUser c){tx=t;budgets=b;goals=g;current=c;}
 @GetMapping("/dashboard/summary") public Map<String,Object> summary(@RequestParam(required=false) String month){AppUser u=current.get();String m=month==null?YearMonth.now().toString():month;List<Transaction> all=tx.findAllByUserOrderByIdDesc(u);BigDecimal income=BigDecimal.ZERO,expense=BigDecimal.ZERO,monthIncome=BigDecimal.ZERO,monthExpense=BigDecimal.ZERO;Map<String,BigDecimal> categories=new TreeMap<>();List<Transaction> recent=all.stream().limit(6).toList();for(Transaction t:all){if(t.getType().equals("INCOME"))income=income.add(t.getAmount());else expense=expense.add(t.getAmount());if(t.getTransactionDate()!=null&&t.getTransactionDate().toString().startsWith(m)){if(t.getType().equals("INCOME"))monthIncome=monthIncome.add(t.getAmount());else{monthExpense=monthExpense.add(t.getAmount());categories.merge(t.getCategory(),t.getAmount(),BigDecimal::add);}}}BigDecimal budgetTotal=budgets.findAllByUserOrderByIdDesc(u).stream().filter(b->b.getMonth().equals(m)).map(Budget::getLimitAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal goalSaved=goals.findAllByUserOrderByIdDesc(u).stream().map(SavingsGoal::getSavedAmount).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,Object> result=new HashMap<>();result.put("income",income);result.put("expenses",expense);result.put("balance",income.subtract(expense));result.put("monthIncome",monthIncome);result.put("monthExpenses",monthExpense);result.put("budgetTotal",budgetTotal);result.put("budgetUsed",monthExpense);result.put("savingsRate",monthIncome.compareTo(BigDecimal.ZERO)>0?monthIncome.subtract(monthExpense).multiply(BigDecimal.valueOf(100)).divide(monthIncome,1,RoundingMode.HALF_UP):BigDecimal.ZERO);result.put("categorySpending",categories);result.put("recentTransactions",recent);result.put("goalSaved",goalSaved);result.put("month",m);return result;}
 @GetMapping("/insights") public List<Map<String,Object>> insights(){AppUser u=current.get();List<Transaction> all=tx.findAllByUserOrderByIdDesc(u);YearMonth now=YearMonth.now(),prev=now.minusMonths(1);Map<String,BigDecimal> cur=new HashMap<>(),old=new HashMap<>();for(Transaction t:all)if("EXPENSE".equals(t.getType())){String ym=t.getTransactionDate().toString().substring(0,7);(ym.equals(now.toString())?cur:ym.equals(prev.toString())?old:new HashMap<>()).merge(t.getCategory(),t.getAmount(),BigDecimal::add);}List<Map<String,Object>> out=new ArrayList<>();for(var e:cur.entrySet()){BigDecimal before=old.getOrDefault(e.getKey(),BigDecimal.ZERO);if(before.signum()>0&&e.getValue().compareTo(before.multiply(new BigDecimal("1.2")))>0)out.add(Map.of("title",e.getKey()+" spending increased","message","Spending is more than 20% higher than last month.","category",e.getKey(),"severity","warning"));}for(Budget b:budgets.findAllByUserOrderByIdDesc(u)){if(!b.getMonth().equals(now.toString()))continue;BigDecimal used=cur.entrySet().stream().filter(e->b.getCategory().equalsIgnoreCase("ALL")||e.getKey().equalsIgnoreCase(b.getCategory())).map(Map.Entry::getValue).reduce(BigDecimal.ZERO,BigDecimal::add);if(used.compareTo(b.getLimitAmount().multiply(new BigDecimal("0.8")))>=0)out.add(Map.of("title","Budget almost used","message",b.getCategory()+" budget is "+used.multiply(BigDecimal.valueOf(100)).divide(b.getLimitAmount(),0,RoundingMode.HALF_UP)+"% used.","category",b.getCategory(),"severity","warning"));}if(out.isEmpty())out.add(Map.of("title","You're on track","message","No significant spending increases or budget threshold alerts were found.","severity","success"));return out;}
}
